167	export const computeELKPositions = async (
168	  nodes: G6NodeData[],
169	  edges: G6EdgeData[],
170	  focusNodeId?: string
171	): Promise<Map<string, { x: number; y: number }>> => {
172	  const partitions = focusNodeId
173	    ? computeDirectedBFSPartitions(nodes, edges, focusNodeId)
174	    : new Map<string, number>();
175	
176	  const elkNodes: ElkNode[] = nodes.map((node) => {
177	    const size = node.style?.size as [number, number] | undefined;
178	    const partition = partitions.get(node.id);
179	
180	    return {
181	      id: node.id,
182	      width: size?.[0] ?? NODE_WIDTH,
183	      height: size?.[1] ?? NODE_HEIGHT,
184	      ...(partition !== undefined && {
185	        layoutOptions: { 'elk.partitioning.partition': String(partition) },
186	      }),
187	    };
188	  });
189	
190	  const elkEdges: ElkExtendedEdge[] = edges.map((edge, i) => {
191	    const rawLabel = edge.data?.['label'];
192	    const labelText = typeof rawLabel === 'string' ? rawLabel : '';
193	    // Estimate label bounding box so ELK auto-expands the corridor to fit it.
194	    // 6.5px/char; labelPadding(6×2) + bgPadding(6×2) + border(1×2) = 26px h.
195	    const labelWidth = Math.ceil(labelText.length * 6.5 + 26);
196	    const labelHeight = 26;
197	
198	    return {
199	      id: String(edge.id ?? `elk-edge-${i}`),
200	      sources: [String(edge.source)],
201	      targets: [String(edge.target)],
202	      labels: [{ text: labelText, width: labelWidth, height: labelHeight }],
203	    };
204	  });
205	
206	  const toPositionMap = (children: ElkNode[]) =>
207	    new Map(children.map((n) => [n.id, { x: n.x ?? 0, y: n.y ?? 0 }]));
208	
209	  try {
210	    const result = await ELKLayout.getElk().layout({
211	      id: 'root',
212	      layoutOptions: ELK_KG_LAYOUT_OPTIONS,
213	      children: elkNodes,
214	      edges: elkEdges,
215	    });
216	
217	    return toPositionMap(result.children ?? []);
218	  } catch {
219	    // Partition constraints on cyclic/cross-path graphs cause ELK to crash with a
220	    // negative-index exception. Retry without partition hints so ELK assigns layers
221	    // automatically — this always succeeds regardless of graph topology.
222	    const elkNodesNoPartitions = elkNodes.map(({ id, width, height }) => ({
223	      id,
224	      width,
225	      height,
226	    }));
