@import (reference) '../../styles/variables.less';

@knowledge-graph-card-header-height: 68px;

.knowledge-graph-empty {
  height: calc(
    @asset-details-tab-pane-height - @knowledge-graph-card-header-height
  );
}

.knowledge-graph-container {
  height: @asset-details-tab-pane-height;
  position: relative;

  .knowledge-graph-canvas {
    height: calc(
      @asset-details-tab-pane-height - @knowledge-graph-card-header-height
    );
    background: #ffffff;
    background-image: radial-gradient(circle, #e8e8e8 1px, transparent 1px);
    background-size: 15px 15px;
    position: relative;
  }

  // Loading and empty states
  .knowledge-graph-loading,
  .knowledge-graph-empty {
    height: 600px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #fafbfc;
    border-radius: 0.75rem;
  }

  .knowledge-graph-action-buttons {
    position: absolute;
    bottom: 16px;
    right: 16px;
    z-index: 1000;
    display: inline-flex;
    background: @white;
    border-radius: 4px;
    border: 1px solid rgba(0, 0, 0, 0.12);
    overflow: hidden;

    .kg-control-btn {
      width: 40px;
      height: 40px;
      display: flex;
      align-items: center;
      justify-content: center;
      background: transparent;
      border: none;
      border-right: 1px solid rgba(0, 0, 0, 0.12);
      cursor: pointer;
      padding: 0;
      color: rgba(0, 0, 0, 0.54);
      transition: background-color 0.15s ease;

      &:last-child {
        border-right: none;
      }

      &:hover {
        background-color: rgba(0, 0, 0, 0.04);
      }

      &:focus-visible {
        outline: 2px solid #1976d2;
        outline-offset: -2px;
      }

      svg {
        width: 16px;
        height: 16px;
      }
    }
  }
}

.full-screen-knowledge-graph {
  position: fixed;
  top: @om-navbar-height;
  left: @sidebar-width;
  width: calc(100vw - @sidebar-width);
  height: calc(100vh - @om-navbar-height - 60px);
  z-index: 999;

  .knowledge-graph-container {
    height: 100%;
    width: 100%;
  }

  &.sidebar-collapsed {
    left: calc(72px + @padding-mlg);
    width: calc(100vw - 72px - @size-xl);
  }

  &.sidebar-expanded {
    left: calc(228px + @padding-mlg);
    width: calc(100vw - 228px - @size-xl);
  }

  .knowledge-graph-canvas {
    width: 100%;
    height: 100%;
  }
}
